import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

// Configuración de IndexedDB
const openDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('FinancialDB', 1);
    
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('financialData')) {
        db.createObjectStore('financialData', { keyPath: 'id' });
      }
    };
    
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const getFinancialData = async () => {
  try {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction('financialData', 'readonly');
      const store = transaction.objectStore('financialData');
      const request = store.get(1);
      
      request.onsuccess = () => resolve(request.result?.data || null);
      request.onerror = () => reject(request.error);
    });
  } catch (error) {
    console.error('Error al obtener datos:', error);
    return null;
  }
};

const saveFinancialData = async (data) => {
  try {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction('financialData', 'readwrite');
      const store = transaction.objectStore('financialData');
      const request = store.put({ id: 1, data });
      
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (error) {
    console.error('Error al guardar datos:', error);
  }
};

const SummaryCard = ({ 
  totalIncome: propTotalIncome = 0, 
  totalExpenses: propTotalExpenses = 0, 
  balance: propBalance = 0, 
  currentBalance: propCurrentBalance = 0 
}) => {
  const [financialData, setFinancialData] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0
  });

  // Cargar datos al montar el componente
  useEffect(() => {
    const loadData = async () => {
      const savedData = await getFinancialData();
      if (savedData) {
        setFinancialData(savedData);
      } else {
        // Si no hay datos guardados, usar las props
        const initialData = {
          totalIncome: propTotalIncome,
          totalExpenses: propTotalExpenses,
          balance: propBalance,
          currentBalance: propCurrentBalance
        };
        setFinancialData(initialData);
        await saveFinancialData(initialData);
      }
    };
    
    loadData();
  }, []);

  // Sincronizar con props y guardar cuando cambien
  useEffect(() => {
    const updateData = async () => {
      const newData = {
        ...financialData,
        ...(propTotalIncome !== undefined && { totalIncome: propTotalIncome }),
        ...(propTotalExpenses !== undefined && { totalExpenses: propTotalExpenses }),
        ...(propBalance !== undefined && { balance: propBalance }),
        ...(propCurrentBalance !== undefined && { currentBalance: propCurrentBalance })
      };
      
      if (JSON.stringify(newData) !== JSON.stringify(financialData)) {
        setFinancialData(newData);
        await saveFinancialData(newData);
      }
    };
    
    updateData();
  }, [propTotalIncome, propTotalExpenses, propBalance, propCurrentBalance]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance.toFixed(2)}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
